-- Read-only, structural signatures. Constraint names generated by SQL Server are not identities.
SELECT CONCAT('TABLE|',s.name,'.',t.name,'|',t.temporal_type,'|',t.is_memory_optimized) AS signature
FROM sys.tables t JOIN sys.schemas s ON s.schema_id=t.schema_id WHERE t.is_ms_shipped=0
UNION ALL
SELECT CONCAT('COLUMN|' COLLATE DATABASE_DEFAULT,s.name,'.',t.name,'|',c.name,'|',TYPE_NAME(c.user_type_id),'|',c.max_length,'|',c.precision,'|',c.scale,
 '|',c.is_nullable,'|',c.is_identity,'|',c.is_computed,'|',COALESCE(c.collation_name,''),'|',COALESCE(d.definition,''),'|',COALESCE(cc.definition,''),
 '|',COALESCE(CONVERT(varchar(50),ic.seed_value),''),'|',COALESCE(CONVERT(varchar(50),ic.increment_value),''),'|',COALESCE(cc.is_persisted,0))
FROM sys.tables t JOIN sys.schemas s ON s.schema_id=t.schema_id JOIN sys.columns c ON c.object_id=t.object_id
LEFT JOIN sys.default_constraints d ON d.object_id=c.default_object_id
LEFT JOIN sys.computed_columns cc ON cc.object_id=c.object_id AND cc.column_id=c.column_id
LEFT JOIN sys.identity_columns ic ON ic.object_id=c.object_id AND ic.column_id=c.column_id WHERE t.is_ms_shipped=0
UNION ALL
SELECT CONCAT('CHECK|' COLLATE DATABASE_DEFAULT,OBJECT_SCHEMA_NAME(parent_object_id),'.',OBJECT_NAME(parent_object_id),'|',definition,'|',is_disabled,'|',is_not_trusted,'|',is_not_for_replication)
FROM sys.check_constraints WHERE is_ms_shipped=0
UNION ALL
SELECT CONCAT('FK|' COLLATE DATABASE_DEFAULT,OBJECT_SCHEMA_NAME(f.parent_object_id),'.',OBJECT_NAME(f.parent_object_id),'|',
 OBJECT_SCHEMA_NAME(f.referenced_object_id),'.',OBJECT_NAME(f.referenced_object_id),'|',
 (SELECT STRING_AGG(CONVERT(nvarchar(max),CONCAT(pc.name,'=',rc.name)),',') WITHIN GROUP(ORDER BY fc.constraint_column_id)
  FROM sys.foreign_key_columns fc JOIN sys.columns pc ON pc.object_id=f.parent_object_id AND pc.column_id=fc.parent_column_id
  JOIN sys.columns rc ON rc.object_id=f.referenced_object_id AND rc.column_id=fc.referenced_column_id WHERE fc.constraint_object_id=f.object_id),
 '|',f.delete_referential_action,'|',f.update_referential_action,'|',f.is_disabled,'|',f.is_not_trusted,'|',f.is_not_for_replication)
FROM sys.foreign_keys f WHERE f.is_ms_shipped=0
UNION ALL
SELECT CONCAT('INDEX|' COLLATE DATABASE_DEFAULT,OBJECT_SCHEMA_NAME(i.object_id),'.',OBJECT_NAME(i.object_id),'|',i.type,'|',i.is_unique,'|',i.is_primary_key,'|',
 i.is_unique_constraint,'|',i.is_disabled,'|',COALESCE(i.filter_definition,''),'|',
 (SELECT STRING_AGG(CONVERT(nvarchar(max),CONCAT(c.name,':',ic.key_ordinal,':',ic.is_descending_key,':',ic.is_included_column)),',') WITHIN GROUP(ORDER BY ic.index_column_id)
  FROM sys.index_columns ic JOIN sys.columns c ON c.object_id=ic.object_id AND c.column_id=ic.column_id WHERE ic.object_id=i.object_id AND ic.index_id=i.index_id))
FROM sys.indexes i JOIN sys.tables t ON t.object_id=i.object_id WHERE t.is_ms_shipped=0 AND i.index_id>0
UNION ALL
SELECT CONCAT('MODULE|' COLLATE DATABASE_DEFAULT,s.name,'.',o.name,'|',o.type,'|',m.uses_ansi_nulls,'|',m.uses_quoted_identifier,'|',m.definition)
FROM sys.sql_modules m JOIN sys.objects o ON o.object_id=m.object_id JOIN sys.schemas s ON s.schema_id=o.schema_id WHERE o.is_ms_shipped=0;
